-- Données d'amorçage générées par scripts/build_seed.py à partir du planning Excel.
-- Relancer le script et ré-exécuter ce fichier si le planning change (les upserts n'écrasent pas les présences).

on conflict (id) do update set libelle = excluded.libelle;

on conflict (id) do update set certificat = excluded.certificat, date = excluded.date, intervenant = excluded.intervenant;

on conflict (id) do update set certificat = excluded.certificat, date = excluded.date, cours = excluded.cours, intervenant = excluded.intervenant;

on conflict (cle) do nothing;
